        beyondP2: { value: "کئی برسوں سے میں نے آڈیو ذرائع کو بھی بائبلی اور الٰہیاتی مواد لوگوں تک پہنچانے کے لیے استعمال کیا ہے، تاکہ وہ لوگ بھی اس تعلیم سے فائدہ اٹھا سکیں جو پڑھنے کے بجائے سننے کے ذریعے سیکھنا پسند کرتے ہیں۔", source: "author", published: true, reviewed: true, sourceHash: "ad7f86083e2bd96b" },
        beyondP3: { value: "اسی سلسلے میں ایک کوشش \"دروازہ درِ حیات\" کے نام سے قائم چینل کے ذریعے بھی رہی ہے، جہاں متعدد مضامین اور بائبلی مطالعات کو آڈیو کی صورت میں بھی پیش کیا گیا۔ ان میں بہت سے خصوصی مضامین بھی شامل رہے ہیں۔", source: "author", published: true, reviewed: true, sourceHash: "9303cecf8132a830" },
        beyondP4: { value: "مقصد ہمیشہ یہی رہا ہے کہ خدا کے کلام کو لوگوں تک پہنچانے کے لیے ہر ذمہ دار اور مؤثر ذریعہ استعمال کیا جائے۔", source: "author", published: true, reviewed: true, sourceHash: "ef6e05681032b68b" },
        beyondP5: { value: "آج ان ذرائع میں شامل ہیں:", source: "author", published: true, reviewed: true, sourceHash: "f8cb60989386a336" },
