        beyondP6: { value: "ہر پلیٹ فارم ایک نئے موقع کی نمائندگی کرتا ہے کہ خدا کے کلام کا پیغام ایسے شخص تک پہنچ سکے جو شاید کسی اور ذریعے سے اس پیغام تک نہ پہنچ پاتا۔", source: "author", published: true, reviewed: true, sourceHash: "436f1d6734ddcc42" },
        voiceHeading: { value: "ایک ایسی آواز جو دور تک پہنچ سکتی ہے", source: "author", published: true, reviewed: true, sourceHash: "909bbb5f6b157e4b" },
        voiceP1: { value: "ہماری نسل کے عظیم مواقع میں سے ایک یہ ہے کہ ایک تحریر اپنے مصنف سے کہیں زیادہ دور تک پہنچ سکتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "1567768c26b9b7b2" },
        voiceP2: { value: "ایک گفتگو شاید ایک شخص تک پہنچے۔", source: "author", published: true, reviewed: true, sourceHash: "7189e33726463b8c" },
        voiceP3: { value: "ایک مضمون سینکڑوں لوگوں تک پہنچ سکتا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "f2eb580ad1fa55a9" },
        voiceP4: { value: "ایک کتاب اپنے مصنف کی تحریر مکمل ہونے کے بہت عرصے بعد بھی لوگوں کو تعلیم دے سکتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "7f45fe94f71e4161" },
        voiceP5: { value: "اور ایک ڈیجیٹل تعلیمی وسیلہ جغرافیائی حدود عبور کرکے ایسے لوگوں تک پہنچ سکتا ہے جن تک عام حالات میں پہنچنا مشکل ہو۔", source: "author", published: true, reviewed: true, sourceHash: "aae11dea81c094c3" },
        voiceP6: { value: "اسی لیے میں تحریر کو محض ذاتی شوق نہیں سمجھتا بلکہ اسے تعلیم اور گواہی کی ایک خدمت سمجھتا ہوں۔", source: "author", published: true, reviewed: true, sourceHash: "58e1744b6ed4cd42" },
        voiceP7: { value: "مقصد لکھنے والے کے لیے شہرت حاصل کرنا نہیں۔", source: "author", published: true, reviewed: true, sourceHash: "91264b52789daa30" },
        voiceP8: { value: "مقصد یہ ہے کہ خدا کے نام کو عزت اور جلال ملے اور بائبلی سچائی کی روشنی اُن لوگوں تک پہنچے جہاں کہیں وہ موجود ہیں۔", source: "author", published: true, reviewed: true, sourceHash: "2c6624bc8199bf5a" },
        purposeHeading: { value: "ہمارا مقصد", source: "author", published: true, reviewed: true, sourceHash: "a71f2e13d411dbfb" },
        purposeP1: { value: "ہر مضمون، ہر کتاب، ہر سبق اور ہر تعلیمی مواد کے پیچھے بنیادی مقصد ایک ہی ہے:", source: "author", published: true, reviewed: true, sourceHash: "97a283f83989882d" },
        purposeP2: { value: "خدا کے کلام کی سچائی کی منادی کرنا، اس کی صداقت اور اختیار کو واضح کرنا، بائبلی اور الٰہیاتی تعلیم فراہم کرنا، اور لوگوں کی مدد کرنا کہ وہ کتابِ مقدس کو سمجھیں اور اُس کے مطابق زندگی گزاریں۔", source: "author", published: true, reviewed: true, sourceHash: "b5c3ac95f19471d1" },
        purposeP3: { value: "چاہے یہ پیغام کسی ویب سائٹ، سوشل میڈیا پیج، مضمون، کتاب، آڈیو ریکارڈنگ یا ہماری واٹس ایپ پر مبنی تھیالوجیکل تعلیم کے ذریعے کسی شخص تک پہنچے، ہم خدا کے شکر گزار ہیں کہ ہمیں اُس کے کلام کو لوگوں تک پہنچانے کا موقع ملتا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "44d188c06faf3246" },
        purposeP4: { value: "ہم یقین رکھتے ہیں کہ ذرائع بدل سکتے ہیں، لیکن بلاہٹ وہی رہتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "f80d75c20ba09b66" },
        purposeP5: { value: "پیغام خدا کا کلام ہے۔", source: "author", published: true, reviewed: true, sourceHash: "f0906d09a870e1fd" },
        purposeP6: { value: "مقصد وفادارانہ تعلیم ہے۔", source: "author", published: true, reviewed: true, sourceHash: "9c199e0b69a1e84b" },
        purposeP7: { value: "خواہش زندگیوں میں تبدیلی دیکھنا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "13d76c24d777c0b2" },
        purposeP8: { value: "اور جلال خدا ہی کے لیے ہے۔", source: "author", published: true, reviewed: true, sourceHash: "7ca343f8193c8ecd" },
        journeyHeading: { value: "یہ سفر جاری ہے", source: "author", published: true, reviewed: true, sourceHash: "197114ad69f0c27a" },
        journeyP1: { value: "جو سفر 17 اگست 2016 کو فیس بک پر ہونے والی گفتگو کے جواب میں تحریر کے ساتھ شروع ہوا تھا، وہ آج ایک جاری تحریری، تعلیمی، تحقیقی اور مسیحی تعلیمی خدمت کی صورت اختیار کر چکا ہے۔", source: "author", published: true, reviewed: true, sourceHash: "9a216af2105e6f05" },
        journeyP2: { value: "یہ سفر ابھی جاری ہے۔", source: "author", published: true, reviewed: true, sourceHash: "b9101d9adb2c13bd" },
        journeyP3: { value: "اب بھی بہت سے سوالات کے جواب دینے ہیں، بہت سے موضوعات کا مطالعہ کرنا ہے، بہت سے مضامین لکھنے ہیں، مزید تعلیمی مواد تیار کرنا ہے اور بہت سی کتابیں مکمل کرنی ہیں۔", source: "author", published: true, reviewed: true, sourceHash: "9e7e15cd47546c83" },
        journeyP4: { value: "میری دعا ہے کہ ہر تحریر اور ہر تیار کیا جانے والا تعلیمی وسیلہ دنیا میں محض ایک اور اشاعت کا اضافہ نہ ہو، بلکہ اس سے کہیں بڑا مقصد پورا کرے۔", source: "author", published: true, reviewed: true, sourceHash: "e0cc004a73b0228a" },
        journeyP5: { value: "خدا کرے ہر مضمون کتابِ مقدس کی طرف ایک دروازہ کھولے۔", source: "author", published: true, reviewed: true, sourceHash: "c2e390061cdc7cf8" },
