        joinUsHeading: { value: "ہمارے ساتھ مل کر تعلیم کو آگے بڑھائیں", source: "author", published: true, reviewed: true, sourceHash: "a45f8bbcbd93e591" },
        joinUsP1: { value: "تعلیمی رسائی ابھی ترقی کے مرحلے میں ہے۔", source: "author", published: true, reviewed: true, sourceHash: "2c0d75989a3f9576" },
        joinUsP2: { value: "ہم خاندانوں سے مل رہے ہیں، والدین کی کونسلنگ کر رہے ہیں، بچوں کی حوصلہ افزائی کر رہے ہیں، جہاں ممکن ہو تعلیمی معاونت فراہم کر رہے ہیں اور اُن لوگوں تک پہنچنے کے بہتر طریقے تلاش کر رہے ہیں جنہیں اس خدمت کی سب سے زیادہ ضرورت ہے۔", source: "author", published: true, reviewed: true, sourceHash: "42eda87ea2e3b1dc" },
        joinUsP3: { value: "لیکن ہم یہ کام اکیلے نہیں کر سکتے۔", source: "author", published: true, reviewed: true, sourceHash: "67565ef907fcaf2a" },
        joinUsP4: { value: "ہمیں ایسے لوگوں کی ضرورت ہے جو یقین رکھتے ہوں کہ ہر بچے کو آگے بڑھنے کا موقع ملنا چاہیے۔", source: "author", published: true, reviewed: true, sourceHash: "11896096e95c8b34" },
