        joinUsP6: { value: "اور سب سے بڑھ کر ہمیں دعا کی ضرورت ہے۔", source: "author", published: true, reviewed: true, sourceHash: "0a5edabacc17dde8" },
        joinUsP7: { value: "آپ کی دعا اس خدمت کو مضبوط کر سکتی ہے۔", source: "author", published: true, reviewed: true, sourceHash: "f6facf3aab0cfe02" },
